#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

class Solution {
public:
    int maxAbsValExpr(vector<int>& arr1, vector<int>& arr2) {
        int res = 0, n = arr1.size();
        for (int p : {-1, 1}) {
            for (int q : {-1, 1}) {
                int minVal = INT_MAX, maxVal = INT_MIN;
                for (int i = 0; i < n; ++i) {
                    int val = p * arr1[i] + q * arr2[i] + i;
                    minVal = min(minVal, val);
                    maxVal = max(maxVal, val);
                }
                res = max(res, maxVal - minVal);
            }
        }
        return res;
    }
};
